context("Cloze cookie and text rendering")

# In the new architecture, cookies are generated by XMLExporter$render_cloze
# (via make_cookie) and the markdown rendering is handled by MarkdownExporter.

# ── Markdown rendering ────────────────────────────────────────────────────────

test_that("MarkdownExporter cloze renders subquestion text with index in parens", {
    q1 <- ClozeQuestion$new(questions = list(Question("sq1", answer = 1)))
    out <- MarkdownExporter$new()$render(instantiate(q1), list())

    expect_true(grepl("sq1 (1)", out, fixed = TRUE))
})

test_that("MarkdownExporter cloze renders two subquestions with consecutive indices", {
    q1 <- ClozeQuestion$new(questions = list(
                                Question("sq1", answer = 1),
                                Question("sq2", answer = 2)))
    out <- MarkdownExporter$new()$render(instantiate(q1), list())

    expect_true(grepl("sq1 (1)", out, fixed = TRUE))
    expect_true(grepl("sq2 (2)", out, fixed = TRUE))
})

test_that("MarkdownExporter cloze feedback shows numbered answers", {
    q1 <- ClozeQuestion$new(questions = list(
                                Question("sq1", answer = 1, feedback = 1),
                                Question("sq2", answer = 2, feedback = 2)))
    out <- MarkdownExporter$new()$render(instantiate(q1), list(feedback = TRUE))

    expect_true(grepl("Réponses", out))
    expect_true(grepl("1\\.", out))
    expect_true(grepl("2\\.", out))
})

# ── XML cookie rendering ──────────────────────────────────────────────────────

test_that("XMLExporter cloze embeds NM cookie with answer value", {
    q1 <- ClozeQuestion$new(questions = list(Question("sq1", answer = 1)))
    out <- XMLExporter$new()$render(instantiate(q1), list(feedback = FALSE))

    expect_true(grepl("NM:=1", out, fixed = TRUE))
    expect_true(grepl('<question type="cloze">', out, fixed = TRUE))
})

test_that("XMLExporter cloze embeds SA cookie for shortanswer subquestion", {
    q1 <- ClozeQuestion$new(questions = list(
                                Question("sq1", type = "shortanswer", answer = "foo")))
    out <- XMLExporter$new()$render(instantiate(q1), list(feedback = FALSE))

    expect_true(grepl("SA:=foo", out, fixed = TRUE))
})
